const raw = $json.content?.parts?.[0]?.text ?? '';
const clean = raw.replace(/```json|```/g, '').trim();

let order;
try {
  order = JSON.parse(clean);
} catch (e) {
  return { json: { valid: false, errors: ['LLM nie zwrócił poprawnego JSON'], raw } };
}

const errors = [];

if (!order.customer_name) errors.push('Brak imienia i nazwiska');
if (!Array.isArray(order.items) || order.items.length === 0) errors.push('Brak pozycji zamówienia');

(order.items || []).forEach((it, i) => {
  if (!Number.isInteger(it.quantity) || it.quantity <= 0) errors.push(`Pozycja ${i + 1}: nieprawidłowa ilość`);
  if (!it.format) errors.push(`Pozycja ${i + 1}: brak formatu`);
});

// Walidacja NIP (suma kontrolna)
if (order.nip) {
  const d = order.nip.replace(/\D/g, '');
  const w = [6, 5, 7, 2, 3, 4, 5, 6, 7];
  const ok = d.length === 10 &&
    w.reduce((s, wi, i) => s + wi * Number(d[i]), 0) % 11 === Number(d[9]);
  if (!ok) errors.push('Nieprawidłowy NIP');
  order.nip = d;
}

if (order.deadline && new Date(order.deadline) < new Date(new Date().toDateString())) {
  errors.push('Termin w przeszłości');
}

errors.push(...(order.missing_info || []).map(f => `Brak danych: ${f}`));

return { json: { valid: errors.length === 0, errors, order } };

const { order, valid, errors } = $('Walidacja').first().json;
const prices = $input.all().map(i => i.json);
const norm = v => String(v ?? '').trim().toLowerCase();

const lines = (order.items || []).map(it => {
  const tier = prices
    .filter(p =>
      norm(p.product) === norm(it.product) &&
      norm(p.format) === norm(it.format) &&
      norm(p.sides) === norm(it.sides ?? '1') &&
      it.quantity >= Number(p.min_qty))
    .sort((a, b) => Number(b.min_qty) - Number(a.min_qty))[0];

  if (!tier) return { ...it, total: null, error: `Brak ceny dla: ${it.product} ${it.format}` };

  const per100 = Number(tier.price_per_100);
  return { ...it, price_per_100: per100, total: Math.round(per100 * it.quantity) / 100 };
});

const pricingErrors = lines.filter(l => l.error).map(l => l.error);
const netto = Math.round(lines.reduce((s, l) => s + (l.total || 0), 0) * 100) / 100;
const vat = Math.round(netto * 0.23 * 100) / 100;

return [{
  json: {
    valid: valid && pricingErrors.length === 0,
    errors: [...errors, ...pricingErrors],
    order,
    lines,
    netto,
    vat,
    brutto: Math.round((netto + vat) * 100) / 100
  }
}];
